blocchi.codice:
extends Control

@onready var title_label: Label = $TitleLabel


func _ready() -> void:
	QuizData.load_topic_records()
	_setup_title_style()


func _setup_title_style() -> void:
	var custom_settings := LabelSettings.new()
	var font_res: Font = load("res://assets/fonts/title_font.ttf")
	custom_settings.font = font_res
	custom_settings.font_size = 32
	custom_settings.outline_size = 6
	custom_settings.outline_color = Color.BLACK
	title_label.label_settings = custom_settings
